CREATE TABLE IF NOT EXISTS host_identity_schema_migrations (
  version INTEGER PRIMARY KEY,
  name TEXT NOT NULL,
  applied_at TEXT NOT NULL
);
CREATE TABLE IF NOT EXISTS host_identity_metadata (
  key TEXT PRIMARY KEY,
  value TEXT NOT NULL
);
CREATE TABLE IF NOT EXISTS platform_principals (
  platform_principal_id TEXT PRIMARY KEY,
  principal TEXT NOT NULL UNIQUE,
  kind TEXT NOT NULL CHECK(kind IN ('user', 'agent', 'service')),
  status TEXT NOT NULL CHECK(status IN ('active', 'suspended', 'revoked')),
  revision INTEGER NOT NULL,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL
);
CREATE TABLE IF NOT EXISTS host_identities (
  identity_id TEXT PRIMARY KEY,
  platform_principal_id TEXT NOT NULL DEFAULT '',
  issuer TEXT NOT NULL,
  external_subject TEXT NOT NULL,
  principal TEXT NOT NULL,
  identifier TEXT NOT NULL DEFAULT '',
  kind TEXT NOT NULL,
  assurance TEXT NOT NULL,
  status TEXT NOT NULL CHECK(status IN ('active', 'suspended', 'revoked')),
  revision INTEGER NOT NULL,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL,
  profile TEXT NOT NULL DEFAULT '{}',
  UNIQUE(issuer, external_subject)
);
CREATE INDEX IF NOT EXISTS host_identities_principal ON host_identities(principal, status);
CREATE TABLE IF NOT EXISTS host_identity_sessions (
  session_hash TEXT PRIMARY KEY,
  identity_id TEXT NOT NULL,
  issued_at TEXT NOT NULL,
  expires_at TEXT NOT NULL,
  last_seen_at TEXT NOT NULL,
  revoked_at TEXT NOT NULL DEFAULT '',
  FOREIGN KEY(identity_id) REFERENCES host_identities(identity_id)
);
CREATE INDEX IF NOT EXISTS host_identity_sessions_identity ON host_identity_sessions(identity_id, expires_at);
CREATE TABLE IF NOT EXISTS host_identity_failures (
  identifier_hash TEXT NOT NULL,
  occurred_at TEXT NOT NULL
);
CREATE INDEX IF NOT EXISTS host_identity_failures_identifier ON host_identity_failures(identifier_hash, occurred_at);
CREATE TABLE IF NOT EXISTS host_identity_events (
  sequence INTEGER PRIMARY KEY AUTOINCREMENT,
  event_id TEXT NOT NULL UNIQUE,
  kind TEXT NOT NULL,
  identity_id TEXT NOT NULL DEFAULT '',
  principal TEXT NOT NULL DEFAULT '',
  occurred_at TEXT NOT NULL,
  detail TEXT NOT NULL DEFAULT '{}'
);
CREATE INDEX IF NOT EXISTS host_identity_events_occurred ON host_identity_events(occurred_at DESC);

INSERT OR IGNORE INTO platform_principals (
  platform_principal_id, principal, kind, status, revision, created_at, updated_at
) VALUES (?, ?, ?, 'active', 1, ?, ?)

